mapper.select:
SELECT CASE WHEN G.ID IS NULL THEN T.ID ELSE G.ID END ID, T.ID as skuId, T.sku_no as skuNo, T.NAME as name, T.status, h.sale_state as saleState, G.currency, G.std_retail_price_vat as stdRetailPriceVat, G.vat_rate as vatRate, G.std_retail_price as stdRetailPrice, j.last_outstock_date as lastOutstockDate, G.update_user_name as updateUserName, G.update_time as updateTime FROM product_detail T LEFT JOIN sku_std_retail_price G ON T.ID = G.sku_id AND G.is_deleted = FALSE LEFT JOIN product_sale h ON T.ID = h.sku_id AND h.is_deleted = FALSE LEFT JOIN sku_biz_statistics j ON T.ID = j.sku_id AND j.is_deleted = FALSE WHERE ${params.sqlMap.default} AND t.is_deleted = false and t.id not in (select distinct bs.parent_sku_id FROM product_bom_sku bs inner JOIN product_bom_info b ON bs.bom_id = b.id AND b.is_deleted = FALSE and b.type ='combination' where bs.is_deleted = false )
and g.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc

SELECT approve_status AS tabFlag, count(*) AS count FROM sku_std_retail_price WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
